/// The tail of every case: a device created with the queried structures chained into its create info, one queue made idle.
macro_rules! create_device_with {
    ($context:expr, $features2:expr) => {{
        let instance = $context.get_instance();
        let physical_device = $context.get_physical_device();
        let queue_priorities = [1.0f32];
        let queue_infos = [vk::DeviceQueueCreateInfo::builder()
            .queue_family_index(0)
            .queue_priorities(&queue_priorities)
            .build()];
        let info = vk::DeviceCreateInfo::builder()
            .queue_create_infos(&queue_infos)
            .push_next(&mut $features2);
        let device = unsafe { instance.create_device(physical_device, &info, None) }.vk_check("vkCreateDevice")?;
        let result = unsafe {
            let queue = device.get_device_queue(0, 0);
            device.queue_wait_idle(queue)
        };
        unsafe { device.destroy_device(None) };
        result.vk_check("vkQueueWaitIdle")?;
        Ok(TestStatus::pass("Pass"))
    }};
}

fn create_device_with_promoted11_structures(context: &Context<'_>) -> TestOutcome {
    let (major, minor, _) = context.api_version();
    if (major, minor) < (1, 1) {
        return Err(TestError::NotSupported("Vulkan 1.1 is not supported".to_string()));
    }

    let mut device16_bit_storage_features = vk::PhysicalDevice16BitStorageFeatures::default();
    let mut device_multiview_features = vk::PhysicalDeviceMultiviewFeatures::default();
    let mut device_protected_memory_features = vk::PhysicalDeviceProtectedMemoryFeatures::default();
    let mut device_sampler_ycbcr_conversion_features = vk::PhysicalDeviceSamplerYcbcrConversionFeatures::default();
    let mut device_shader_draw_parameters_features = vk::PhysicalDeviceShaderDrawParametersFeatures::default();
    let mut device_variable_pointers_features = vk::PhysicalDeviceVariablePointersFeatures::default();
    let mut features2 = vk::PhysicalDeviceFeatures2::builder()
        .push_next(&mut device16_bit_storage_features)
        .push_next(&mut device_multiview_features)
        .push_next(&mut device_protected_memory_features)
        .push_next(&mut device_sampler_ycbcr_conversion_features)
        .push_next(&mut device_shader_draw_parameters_features)
        .push_next(&mut device_variable_pointers_features);
    unsafe {
        context
            .get_instance()
            .get_physical_device_features2(context.get_physical_device(), &mut features2)
    };

    create_device_with!(context, features2)
}

